import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {createRequire} from 'node:module';
import {pathToFileURL} from 'node:url';
assert.equal(process.env.KB_T022_PRIVATE_REVIEW_TESTS, '1', 'Explicit local private opt-in required');
const root=process.cwd(), sha=bytes=>createHash('sha256').update(bytes).digest('hex');
const specPath='qa/evidence/goal-t022-offline-review-local-authorized-spec.json';
const sourceSpecBytes=fs.readFileSync(specPath);
assert.equal(sha(sourceSpecBytes),'f7ca4901ed586433cc1d761fcd1dbfae07545b919a6da453e2deb66471b6387d','Source specification changed');
const sourceSpec=JSON.parse(sourceSpecBytes);
const manifestPath='qa/manifests/goal-t022-offline-review.md', packetPath='qa/packets/goal-t022-offline-review.md';
const manifest=fs.readFileSync(manifestPath,'utf8');
assert.match(manifest,/^Status: ready-for-check\s*$/m,'Wait for formal READY');
assert.match(manifest,/^Fix cycle: 0\s*$/m,'Wrong check cycle');
const artifactPath='data/eval/t022-offline-review.html';
const paths=[...new Set([...sourceSpec.pins.map(p=>p.path),artifactPath,manifestPath,packetPath,'qa/contracts/goal-t022-offline-review.md'])];
const pins=()=>Object.fromEntries(paths.map(p=>[p,sha(fs.readFileSync(p))]));
const before=pins();
for(const pin of sourceSpec.pins){assert.equal(before[pin.path],pin.sha256,'Source pin mismatch');assert.equal(fs.statSync(pin.path).size,pin.bytes,'Source size mismatch');}
assert.equal(before['qa/contracts/goal-t022-offline-review.md'],'e6a24a9598d33f9fd0de9bed41b85572fee69e6a7a87fe0ac306be3e769097e1');
const {currentOfflineSnapshot,renderOfflineHtml}=await import(pathToFileURL(path.resolve(root,'scripts/eval/t022-offline-review.mjs')).href);
const snapshot=await currentOfflineSnapshot(path.resolve(root,'data/eval/calibration-human-review.json'));
assert.equal(snapshot.packet.items.length,30);assert.equal(snapshot.packet.sources.length,44);
const html=fs.readFileSync(artifactPath,'utf8'), marker='\nofflinePage(', start=html.lastIndexOf(marker), end=html.lastIndexOf(');</script></html>');
assert.ok(start>=0&&end>start,'Generated artifact envelope missing');
const embedded=JSON.parse(html.slice(start+marker.length,end));
assert.deepEqual(embedded.packet,snapshot.packet);assert.equal(embedded.packetSha256,snapshot.packetSha256);
assert.equal(new Date(embedded.generatedAt).toISOString(),embedded.generatedAt);
assert.equal(html,renderOfflineHtml(embedded),'Emitted HTML differs from checked helper rendering');
const {JSDOM}=createRequire(path.resolve(root,'apps/web/package.json'))('jsdom');
const downloads=[], startedAt=new Date().toISOString();
let calls=0;
const dom=new JSDOM(html,{runScripts:'dangerously',url:'file:///private-t022-artifact-check.html',beforeParse(window){
window.Blob=Blob;window.URL.createObjectURL=blob=>{downloads.push(blob);return 'blob:local-private-check';};
window.URL.revokeObjectURL=()=>{};window.HTMLAnchorElement.prototype.click=()=>{};
window.fetch=()=>{calls++;throw Error('Network forbidden');};
window.XMLHttpRequest=function(){calls++;throw Error('Network forbidden');};
window.WebSocket=function(){calls++;throw Error('Network forbidden');};
}});
try{
const el=id=>dom.window.document.getElementById(id);
assert.equal(el('item').options.length,30);assert.equal(el('item').children.length,3);
let displayed=0;
for(const item of snapshot.packet.items){
el('item').value=item.id;el('item').dispatchEvent(new dom.window.Event('change',{bubbles:true}));
assert.equal(el('query').textContent,item.query);assert.equal(el('title').textContent,item.node.title);
assert.equal(el('summary').textContent,item.node.summary);assert.equal(el('input').textContent,item.inputSha256);
assert.equal(el('score').value,'');assert.equal(el('rationale').value,'');assert.equal(el('affirm').checked,false);displayed++;
}
assert.equal(el('rubric').textContent,snapshot.packet.rubric);assert.equal(el('complete').disabled,true);
assert.match(el('binding').textContent,new RegExp(snapshot.packetSha256));assert.match(el('progress').textContent,/Memory-only/);
assert.equal(dom.window.document.querySelectorAll('script[src],link,img,iframe,svg').length,0);
assert.match(dom.window.document.querySelector('meta[http-equiv="Content-Security-Policy"]').content,/connect-src 'none'/);
const draft=dom.window.t022CurrentDraft();
assert.equal(draft.submittedCount,0);assert.equal(draft.pendingCount,30);assert.equal(draft.completeAssertions,false);
assert.equal(draft.humanGoldVerified,false);assert.equal(draft.serverAuditAuthoritative,false);
assert.ok(draft.items.every(i=>i.localRevision===0&&i.serverExpectedRevision===null&&i.score===null&&i.rationale===null&&i.affirmIndividualReview===false&&i.assertedBy===null&&i.assertedAt===null));
el('backup').click();assert.equal(downloads.length,1);
const exported=JSON.parse(await downloads[0].text());
assert.equal(exported.format,'calibration-offline-draft-v1');assert.deepEqual(exported.packet,snapshot.packet);
assert.equal(exported.submittedCount,0);assert.equal(exported.pendingCount,30);
assert.equal(exported.humanGoldVerified,false);assert.equal(exported.serverAuditAuthoritative,false);
const {validateHumanCalibrationInputs}=await import(pathToFileURL(path.resolve(root,'scripts/eval/human-calibration.mjs')).href);
await assert.rejects(validateHumanCalibrationInputs(exported,null),/authoritative stored-review export/);
assert.equal(calls,0);const after=pins();assert.deepEqual(after,before,'Artifact or source drift');
console.log(JSON.stringify({scope:'Independent actual emitted private HTML/current-source neutral-input/draft-consumer acceptance',startedAt,completedAt:new Date().toISOString(),actualArtifactSha256:sha(html),packetSha256:snapshot.packetSha256,displayedItems:displayed,sourceBindings:44,pending:30,fictionalJudgmentsEntered:0,genuineHumanJudgments:0,networkCalls:calls,providerCalls:0,dbCalls:0,browserCalls:0,downloadedDraftRejectedByLiveIntake:true,before,after,hashesUnchanged:true,noPrivateTextOutput:true}));
}finally{dom.window.close();}
